"""Strict schema of the catalogue seed document (`seed_v1.json`, generated by the web app).

Field limits mirror the column sizes of migration 0009, so an invalid document fails here with a
readable message instead of as a database error halfway through a seed.
"""

from __future__ import annotations

from typing import Annotated, Literal

from pydantic import BaseModel, ConfigDict, Field, StringConstraints

from app.models import CATALOGUE_KEY_PATTERN, SLUG_PATTERN, ServiceKey

SEED_SCHEMA_VERSION = 1

Key = Annotated[str, StringConstraints(pattern=r"^[a-z][a-z0-9_]*$", max_length=80)]
QualifiedKey = Annotated[str, StringConstraints(pattern=CATALOGUE_KEY_PATTERN, max_length=80)]
Slug = Annotated[str, StringConstraints(pattern=SLUG_PATTERN, max_length=80)]
Icon = Annotated[str, StringConstraints(pattern=r"^[a-zA-Z][a-zA-Z0-9]*$", max_length=32)]


def _text(max_length: int) -> StringConstraints:
    return StringConstraints(strip_whitespace=True, min_length=1, max_length=max_length)


Name = Annotated[str, _text(160)]
ShortName = Annotated[str, _text(80)]
Summary = Annotated[str, _text(300)]
Body = Annotated[str, _text(2000)]
Label = Annotated[str, _text(80)]
Prerequisite = Annotated[str, _text(400)]
SeoTitle = Annotated[str, _text(70)]
SeoDescription = Annotated[str, _text(175)]
Keyword = Annotated[str, _text(100)]


class SeedModel(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)


class PerLocale[T: SeedModel](SeedModel):
    """Both locales are required: published domains, families and services exist in BG and EN."""

    bg: T
    en: T


class DomainText(SeedModel):
    slug: Slug
    name: Name
    summary: Summary
    body: Body
    cta_label: Label
    seo_title: SeoTitle
    seo_description: SeoDescription
    primary_keyword: Keyword | None


class FamilyText(SeedModel):
    name: Name
    summary: Summary
    prerequisite: Prerequisite | None


class ServiceText(SeedModel):
    slug: Slug
    name: Name
    short_name: ShortName
    summary: Summary
    body: Body
    seo_title: SeoTitle
    seo_description: SeoDescription
    primary_keyword: Keyword | None


Status = Literal["draft", "published", "archived"]
Delivery = Literal["available", "custom", "planned"]


class DomainSeed(SeedModel):
    key: Key
    code: Annotated[str, StringConstraints(pattern=r"^[A-Z]$")]
    band: Literal["ai", "engineering", "operations"]
    icon: Icon
    position: int = Field(ge=0, le=32_767)
    status: Status
    contact_service: Key
    related: list[Key]
    translations: PerLocale[DomainText]


class FamilySeed(SeedModel):
    key: QualifiedKey
    domain: Key
    delivery_status: Delivery
    position: int = Field(ge=0, le=32_767)
    status: Status
    services: list[Key]
    via: list[Key]
    translations: PerLocale[FamilyText]


class ServiceSeed(SeedModel):
    key: Key
    primary_domain: Key
    offering_type: Literal["service"]
    delivery_status: Delivery
    lead_category: ServiceKey
    icon: Icon
    custom_page: bool
    is_entry_offer: bool
    position: int = Field(ge=0, le=32_767)
    status: Status
    related: list[Key]
    translations: PerLocale[ServiceText]


class SeedDocument(SeedModel):
    schema_version: Literal[1]
    locales: list[Literal["bg", "en"]]
    domains: list[DomainSeed]
    families: list[FamilySeed]
    services: list[ServiceSeed]
